import { CanActivate, ExecutionContext, Injectable } from "@nestjs/common"

@Injectable()
export class ApiKeyGuard implements CanActivate {
    canActivate(context: ExecutionContext): boolean {
        const request = context.switchToHttp().getRequest()
        return request.headers["x-api-key"] === "sirli-kalit"   // true — o'tadi, false — 403
    }
}

canActivate(context: ExecutionContext): boolean {
    const role = context.switchToHttp().getRequest().headers["x-role"]
    if (!role) throw new UnauthorizedException("Avval tizimga kiring")   // 401: kimligingiz noma'lum
    if (role !== "admin") throw new ForbiddenException("Faqat adminlar uchun")   // 403: kimligingiz ma'lum, ruxsat yo'q
    return true
}

canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest()
    console.log(request.method, request.url)                         // GET /reports/monthly
    console.log(context.getClass().name, context.getHandler().name)  // ReportsController monthly
    console.log(context.getType())                                   // http
    return true
}

