import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, Param, UseGuards } from "@nestjs/common"

const users: Record<string, { id: string; role: string }> = {
    a: { id: "1", role: "user" }, b: { id: "2", role: "user" }, z: { id: "99", role: "admin" },
}

@Injectable()
class OwnerOrAdminGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const me = users[req.headers["x-user"]]
        if (me?.role === "admin" || me?.id === req.params.id) return true
        throw new ForbiddenException("Faqat o'z profilingizni ko'ra olasiz")
    }
}

@Controller("users")
class UsersController {
    @Get(":id/orders") @UseGuards(OwnerOrAdminGuard)
    orders(@Param("id") id: string) { return { userId: id, orders: 3 } }
}

@Module({ controllers: [UsersController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/users/1/orders", { "x-user": "a" })
    await http.get("/users/1/orders", { "x-user": "b" })
    await http.get("/users/1/orders", { "x-user": "z" })
    await http.close()
}
main()

