import { CanActivate, Controller, ExecutionContext, Get, Injectable, mixin, Module, Type, UseGuards, BadRequestException } from "@nestjs/common"

function RequireHeader(name: string): Type<CanActivate> {
    @Injectable()
    class RequireHeaderGuard implements CanActivate {
        canActivate(ctx: ExecutionContext) {
            if (!ctx.switchToHttp().getRequest().headers[name]) throw new BadRequestException(`"${name}" sarlavhasi kerak`)
            return true
        }
    }
    return mixin(RequireHeaderGuard)
}

@Controller("api")
