    @Get("mobile") @UseGuards(RequireHeader("x-app-version")) mobile() { return "mobil API" }
    @Get("partner") @UseGuards(RequireHeader("x-partner-id")) partner() { return "hamkor API" }
}
@Module({ controllers: [ApiController] }) class AppModule {}

