import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, UseGuards } from "@nestjs/common"

@Injectable()
class LicenseGuard implements CanActivate {
    private cache = new Map<string, { ok: boolean; until: number }>()
    checks = 0
    private async checkRemote(key: string) { this.checks++; await new Promise(r => setTimeout(r, 5)); return key === "LIC-123" }
    async canActivate(ctx: ExecutionContext) {
        const key = ctx.switchToHttp().getRequest().headers["x-license"] ?? ""
        const hit = this.cache.get(key)
        if (hit && hit.until > Date.now()) return hit.ok
        const ok = await this.checkRemote(key)
        this.cache.set(key, { ok, until: Date.now() + 60_000 })
        return ok
    }
}

@Controller("pro") @UseGuards(LicenseGuard)
class ProController { @Get() get() { return "pro funksiya" } }
@Module({ controllers: [ProController], providers: [LicenseGuard] }) class AppModule {}

