import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, UseGuards } from "@nestjs/common"
import { getRepositoryToken, InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class User { @PrimaryGeneratedColumn() id: number; @Column() name: string; @Column({ default: false }) banned: boolean }

@Injectable()
class NotBannedGuard implements CanActivate {
    constructor(@InjectRepository(User) private readonly users: Repository<User>) {}
    async canActivate(ctx: ExecutionContext) {
        const id = Number(ctx.switchToHttp().getRequest().headers["x-user-id"])
        const user = await this.users.findOneBy({ id })
        if (user?.banned) throw new ForbiddenException("Hisobingiz bloklangan")
        return !!user
    }
}

@Controller("feed") @UseGuards(NotBannedGuard)
class FeedController { @Get() feed() { return ["post 1", "post 2"] } }
@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User], synchronize: true }), TypeOrmModule.forFeature([User])], controllers: [FeedController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get<Repository<User>>(getRepositoryToken(User)).save([{ name: "Ali" }, { name: "Spamer", banned: true }])
    await http.get("/feed", { "x-user-id": "1" })
    await http.get("/feed", { "x-user-id": "2" })
    await http.close()
}
main()

