import { ArgumentsHost, CanActivate, Catch, Controller, ExceptionFilter, ExecutionContext, ForbiddenException, Get, HttpException, Injectable, Module, UseGuards } from "@nestjs/common"

@Injectable()
class StaffGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const role = ctx.switchToHttp().getRequest().headers["x-role"]
        if (role === "guest") throw new ForbiddenException("Faqat xodimlar uchun")
        return role === "staff"      // false bo'lsa — standart "Forbidden resource"
    }
}

@Catch(HttpException)
class EnvelopeFilter implements ExceptionFilter {
    catch(exception: HttpException, host: ArgumentsHost) {
        const status = exception.getStatus()
        host.switchToHttp().getResponse().status(status).json({ ok: false, status, sabab: exception.message })
    }
}

