import { CanActivate, Controller, ExecutionContext, Get, Module } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

const Roles = Reflector.createDecorator<string[]>()

// @Injectable() ham, APP_GUARD ham yo'q: guard'ni main.ts'da o'zimiz yaratamiz
class RolesGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const roles = this.reflector.getAllAndOverride(Roles, [ctx.getHandler(), ctx.getClass()])
        return !roles || roles.includes(ctx.switchToHttp().getRequest().headers["x-role"])
    }
}

@Controller()
