import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, Post, SetMetadata, UnauthorizedException, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

const keys: Record<string, string[]> = { "key-read": ["read"], "key-full": ["read", "write"] }
const Scope = (s: string) => SetMetadata("scope", s)

@Injectable()
class ApiKeyGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const key = ctx.switchToHttp().getRequest().headers["x-api-key"]
        const scopes = keys[key]
        if (!scopes) throw new UnauthorizedException("API kalit noto'g'ri")
        const need = this.reflector.get<string>("scope", ctx.getHandler())
        if (need && !scopes.includes(need)) throw new ForbiddenException(`"${need}" ruxsati yo'q`)
        return true
    }
}

