@Injectable()
class JwtOrApiKeyGuard implements CanActivate {
    constructor(private readonly jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        if (req.headers["x-api-key"] === "srv-key-1") { req.principal = { type: "service", id: "billing" }; return true }
        const token = req.headers.authorization?.replace("Bearer ", "")
        if (token) {
            const p = await this.jwt.verifyAsync(token).catch(() => null)
            if (p) { req.principal = { type: "user", id: p.sub }; return true }
        }
        throw new UnauthorizedException("JWT yoki API kalit kerak")
    }
}

