        const header: string = ctx.switchToHttp().getRequest().headers.authorization ?? ""
        const given = Buffer.from(Buffer.from(header.replace("Basic ", ""), "base64").toString())
        const ok = given.length === this.expected.length && timingSafeEqual(given, this.expected)
        if (!ok) {
            ctx.switchToHttp().getResponse().setHeader("WWW-Authenticate", 'Basic realm="admin"')
            throw new UnauthorizedException()
        }
        return true
    }
}

