import { Body, Controller, HttpException, HttpStatus, Injectable, Module, Post, UnauthorizedException } from "@nestjs/common"

@Injectable()
class LoginAttempts {
    private fails = new Map<string, { count: number; until: number }>()
    check(email: string) {
        const f = this.fails.get(email)
        if (f && f.until > Date.now()) throw new HttpException("Juda ko'p urinish. 15 daqiqadan keyin qayta urinib ko'ring", HttpStatus.TOO_MANY_REQUESTS)
    }
    fail(email: string) {
        const f = this.fails.get(email) ?? { count: 0, until: 0 }
        f.count++
        if (f.count >= 3) f.until = Date.now() + 15 * 60_000
        this.fails.set(email, f)
    }
    reset(email: string) { this.fails.delete(email) }
}

@Controller("auth")
class AuthController {
    constructor(private readonly attempts: LoginAttempts) {}
    @Post("login") login(@Body() b: { email: string; password: string }) {
        this.attempts.check(b.email)
        if (b.password !== "togri") { this.attempts.fail(b.email); throw new UnauthorizedException("Parol noto'g'ri") }
        this.attempts.reset(b.email)
        return { ok: true }
    }
}
