import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

@Injectable()
class AccessGuard implements CanActivate {
    constructor(private readonly jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const token = (req.headers.authorization ?? "").replace(/^Bearer /, "")
        const payload = await this.jwt.verifyAsync<{ sub: number; type: string }>(token).catch(() => null)
