@Injectable()
class UsersService {
    // foydalanuvchi id → parol oxirgi marta o'zgargan vaqt (unix soniya)
    passwordChangedAt = new Map<number, number>([[1, 2_000_000]])
}

@Injectable()
class AuthGuard implements CanActivate {
    constructor(private readonly jwt: JwtService, private readonly users: UsersService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const token = (req.headers.authorization ?? "").replace(/^Bearer /, "")
        const payload = await this.jwt.verifyAsync<{ sub: number; iat: number }>(token).catch(() => null)
        if (!payload) throw new UnauthorizedException("Token yaroqsiz")
        if (payload.iat < (this.users.passwordChangedAt.get(payload.sub) ?? 0)) {
            throw new UnauthorizedException("Parol o'zgargan, qayta kiring")
        }
        req.user = { id: payload.sub }
        return true
    }
}

