import { CanActivate, Controller, Delete, ExecutionContext, Get, Injectable, Module, SetMetadata, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

const Roles = (...roles: string[]) => SetMetadata("roles", roles)
