const ROLE_PERMISSIONS: Record<string, string[]> = {
    author: ["posts:read", "posts:create"],
    moderator: ["posts:read", "posts:delete"],
}
const Permissions = Reflector.createDecorator<string[]>()

@Injectable()
class PermissionsGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const need = this.reflector.get(Permissions, ctx.getHandler()) ?? []
        const have = ROLE_PERMISSIONS[ctx.switchToHttp().getRequest().headers["x-role"]] ?? []
        const missing = need.filter(p => !have.includes(p))
        if (missing.length) throw new ForbiddenException(`Yetishmayotgan huquq: ${missing.join(", ")}`)
        return true
    }
}

