import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, UnauthorizedException, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"
import { JwtModule, JwtService } from "@nestjs/jwt"

const Roles = Reflector.createDecorator<string[]>()

@Injectable()
class JwtRolesGuard implements CanActivate {
    constructor(private readonly jwt: JwtService, private readonly reflector: Reflector) {}
    async canActivate(ctx: ExecutionContext) {
        const token = ctx.switchToHttp().getRequest().headers.authorization?.slice(7)
        const payload = await this.jwt.verifyAsync(token ?? "").catch(() => null)
        if (!payload) throw new UnauthorizedException()
        const roles = this.reflector.get(Roles, ctx.getHandler())
        if (roles && !roles.includes(payload.role)) throw new ForbiddenException(`${payload.role} uchun ruxsat yo'q`)
        return true
    }
}

