type User = { id: number; role: "user" | "moderator" }
type Policy = (user: User, params: Record<string, string>) => boolean
const CheckPolicy = (p: Policy) => SetMetadata("policy", p)

const comments = new Map([[1, { authorId: 1 }], [2, { authorId: 2 }]])

@Injectable()
class PolicyGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const policy = this.reflector.get<Policy>("policy", ctx.getHandler())
        const req = ctx.switchToHttp().getRequest()
        const user: User = { id: Number(req.headers["x-user-id"]), role: req.headers["x-role"] ?? "user" }
        if (!policy(user, req.params)) throw new ForbiddenException("Siyosat bo'yicha ruxsat yo'q")
        return true
    }
}

