import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, Req, UseGuards } from "@nestjs/common"

@Injectable()
class ImpersonationGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        req.user = { id: Number(req.headers["x-user-id"]), role: req.headers["x-role"] ?? "user" }
        const as = req.headers["x-act-as"]
        if (as) {
            if (req.user.role !== "admin") throw new ForbiddenException("Faqat admin boshqa nomidan harakat qila oladi")
            req.actor = req.user
            req.user = { id: Number(as), role: "user" }
        }
        return true
    }
}

