import { Controller, Get, Module, SetMetadata } from "@nestjs/common"
import { DiscoveryModule, DiscoveryService, MetadataScanner, NestFactory, Reflector } from "@nestjs/core"

const Roles = (...r: string[]) => SetMetadata("roles", r)
@Controller("x") class X { @Get("a") @Roles("admin") a() {} @Get("b") @Roles("user", "admin") b() {} @Get("c") c() {} }
@Module({ imports: [DiscoveryModule], controllers: [X] }) class AppModule {}

async function main() {
    const ctx = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ref = ctx.get(Reflector), scanner = ctx.get(MetadataScanner)
    for (const w of ctx.get(DiscoveryService).getControllers()) {
        const proto = Object.getPrototypeOf(w.instance)
        for (const m of scanner.getAllMethodNames(proto)) console.log(`${w.name}.${m}:`, ref.get("roles", proto[m]) ?? "ochiq")
    }
    await ctx.close()
}
