import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, SetMetadata, UnauthorizedException } from "@nestjs/common"
import { APP_GUARD, Reflector } from "@nestjs/core"

const Public = () => SetMetadata("isPublic", true)
const Roles = Reflector.createDecorator<string[]>()
const sessions: Record<string, { name: string; role: string }> = {
    t1: { name: "Ali", role: "user" },
    t2: { name: "Bek", role: "admin" },
}

@Injectable()
class AuthGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        console.log("  AuthGuard")
        if (this.reflector.getAllAndOverride<boolean>("isPublic", [ctx.getHandler(), ctx.getClass()])) return true
        const req = ctx.switchToHttp().getRequest()
        req.user = sessions[req.headers["x-token"]]
        if (!req.user) throw new UnauthorizedException()
        return true
    }
}

@Injectable()
class RolesGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        console.log("  RolesGuard")
        const roles = this.reflector.getAllAndOverride(Roles, [ctx.getHandler(), ctx.getClass()])
        if (!roles) return true
        const user = ctx.switchToHttp().getRequest().user
        if (!roles.includes(user?.role)) throw new ForbiddenException("Kerakli rol: " + roles.join(", "))
        return true
    }
}

@Controller()
class AppController {
    @Public() @Get("health") health() { return { status: "up" } }
    @Roles(["admin"]) @Get("stats") stats() { return { users: 1520 } }
}

@Module({
    controllers: [AppController],
    providers: [
        { provide: APP_GUARD, useClass: AuthGuard },    // providers ro'yxatidagi tartibda ishlaydi
        { provide: APP_GUARD, useClass: RolesGuard },
    ],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/health")
    await http.get("/stats")
    await http.get("/stats", { "x-token": "t1" })
    await http.get("/stats", { "x-token": "t2" })
    await http.close()
}
