import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, SetMetadata } from "@nestjs/common"
import { APP_GUARD, Reflector } from "@nestjs/core"

const IS_PUBLIC = "isPublic"
const Public = () => SetMetadata(IS_PUBLIC, true)
const Roles = Reflector.createDecorator<string[]>()

@Injectable()
class DenyByDefaultGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const targets = [ctx.getHandler(), ctx.getClass()]
        if (this.reflector.getAllAndOverride<boolean>(IS_PUBLIC, targets)) return true
        const roles = this.reflector.getAllAndOverride(Roles, targets)
        if (!roles) throw new ForbiddenException("Endpoint yopiq: @Public() yoki @Roles() belgilanmagan")
        return roles.includes(ctx.switchToHttp().getRequest().headers["x-role"])
    }
}

@Controller()
class AppController {
    @Public() @Get("health") health() { return "ok" }
    @Roles(["user", "admin"]) @Get("orders") orders() { return ["#1001"] }
    @Get("forgotten") forgotten() { return "bu yerga hech kim kirmasligi kerak edi" }
}

@Module({ controllers: [AppController], providers: [{ provide: APP_GUARD, useClass: DenyByDefaultGuard }] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/health")
    await http.get("/orders", { "x-role": "user" })
    await http.get("/orders")
    await http.get("/forgotten", { "x-role": "admin" })
    await http.close()
}
