import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

const INHERITS: Record<string, string[]> = { admin: ["manager"], manager: ["user"], user: [] }

// rolning o'zi va u meros olgan barcha rollarni yig'adi
function expandRoles(role: string, seen = new Set<string>()): Set<string> {
    if (seen.has(role)) return seen
    seen.add(role)
    for (const child of INHERITS[role] ?? []) expandRoles(child, seen)
    return seen
}

const Roles = Reflector.createDecorator<string[]>()

@Injectable()
class HierarchyGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const required = this.reflector.get(Roles, ctx.getHandler())
        if (!required) return true
        const role = String(ctx.switchToHttp().getRequest().headers["x-role"] ?? "")
        const effective = expandRoles(role)
        return required.some(r => effective.has(r))
    }
}

@Controller("app")
@UseGuards(HierarchyGuard)
class AppController {
    @Get("feed") @Roles(["user"]) feed() { return "lenta" }
    @Get("reports") @Roles(["manager"]) reports() { return "hisobotlar" }
    @Get("settings") @Roles(["admin"]) settings() { return "sozlamalar" }
}

@Module({ controllers: [AppController] })
class AppModule {}

async function main() {
    console.log("admin ega bo'lgan rollar:", [...expandRoles("admin")])
    const http = await testApp(AppModule)
    await http.get("/app/feed", { "x-role": "manager" })
    await http.get("/app/settings", { "x-role": "manager" })
    await http.get("/app/reports", { "x-role": "admin" })
    await http.close()
}
main()

import { CanActivate, Controller, Delete, ExecutionContext, Get, Injectable, Module, Param, SetMetadata, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

type Action = "read" | "update" | "delete"
interface Ability { can(action: Action, subject: string): boolean }
interface IPolicyHandler { handle(ability: Ability): boolean }
type PolicyHandler = IPolicyHandler | ((ability: Ability) => boolean)

const CHECK_POLICIES_KEY = "check_policy"
const CheckPolicies = (...handlers: PolicyHandler[]) => SetMetadata(CHECK_POLICIES_KEY, handlers)

const RULES: Record<string, [Action, string][]> = {
    reader: [["read", "Article"]],
    admin: [["read", "Article"], ["update", "Article"], ["delete", "Article"]],
}

@Injectable()
class AbilityFactory {
    createForRole(role: string): Ability {
        const rules = RULES[role] ?? []
        return { can: (action, subject) => rules.some(([a, s]) => a === action && s === subject) }
    }
}

@Injectable()
class PoliciesGuard implements CanActivate {
    constructor(private readonly reflector: Reflector, private readonly abilities: AbilityFactory) {}
    canActivate(ctx: ExecutionContext) {
        const handlers = this.reflector.get<PolicyHandler[]>(CHECK_POLICIES_KEY, ctx.getHandler()) ?? []
        const ability = this.abilities.createForRole(String(ctx.switchToHttp().getRequest().headers["x-role"] ?? ""))
        return handlers.every(h => (typeof h === "function" ? h(ability) : h.handle(ability)))
    }
}

class ReadArticlePolicy implements IPolicyHandler {
    handle(ability: Ability) { return ability.can("read", "Article") }
}

@Controller("articles")
@UseGuards(PoliciesGuard)
class ArticlesController {
    @Get() @CheckPolicies(new ReadArticlePolicy())
    list() { return ["maqola-1"] }

    @Delete(":id") @CheckPolicies(ability => ability.can("delete", "Article"))
    remove(@Param("id") id: string) { return { deleted: id } }
}

@Module({ controllers: [ArticlesController], providers: [AbilityFactory] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/articles", { "x-role": "reader" })
    await http.delete("/articles/1", { "x-role": "reader" })
    await http.delete("/articles/1", { "x-role": "admin" })
    await http.get("/articles")
    await http.close()
}
main()

import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, Post, UnauthorizedException, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"
import { JwtModule, JwtService } from "@nestjs/jwt"

const Scopes = Reflector.createDecorator<string[]>()

@Injectable()
class ScopesGuard implements CanActivate {
    constructor(private readonly jwt: JwtService, private readonly reflector: Reflector) {}
    async canActivate(ctx: ExecutionContext) {
        const token = String(ctx.switchToHttp().getRequest().headers.authorization ?? "").replace(/^Bearer /, "")
        const payload = await this.jwt.verifyAsync<{ scope?: string }>(token).catch(() => null)
        if (!payload) throw new UnauthorizedException()
        const needed = this.reflector.get(Scopes, ctx.getHandler()) ?? []
        const granted = new Set((payload.scope ?? "").split(" "))      // "posts:read posts:write" → Set
        const missing = needed.filter(s => !granted.has(s))
        if (missing.length) throw new ForbiddenException("Yetishmayotgan scope: " + missing.join(", "))
        return true
    }
}

@Controller("posts")
@UseGuards(ScopesGuard)
class PostsController {
    @Get() @Scopes(["posts:read"]) list() { return ["post-1"] }
    @Post() @Scopes(["posts:read", "posts:write"]) create() { return { created: true } }
}

@Module({ imports: [JwtModule.register({ secret: "maxfiy" })], controllers: [PostsController], providers: [ScopesGuard] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const jwt = http.app.get(JwtService)
    const reader = await jwt.signAsync({ sub: 1, scope: "posts:read" })
    const writer = await jwt.signAsync({ sub: 2, scope: "posts:read posts:write" })
    await http.get("/posts", { authorization: "Bearer " + reader })
    await http.post("/posts", {}, { authorization: "Bearer " + reader })
    await http.post("/posts", {}, { authorization: "Bearer " + writer })
    await http.get("/posts")
    await http.close()
}
main()
